const P2_DOM=[["network",APPC,"Grace"],["retail",APPC,"head of retail"],["finance",APPC,"head of finance"],["enterprise",[176,196,255],"Ama"]];
const P2_CAPS=["bring in","store","process","serve","govern","secure","orchestrate","observe"];
